118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        // Normalize the address up front so every downstream use (the required-field check,
122	        // household-duplicate detection, the shared household id and the stored/returned value)
123	        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
124	        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
125	        // supplied line is normalized the same way, and the composed address is the normalized
126	        // addressLine1 with a single space and the normalized addressLine2 appended when present.
127	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
128	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
129	        boolean structuredAddress = !isBlank(normalizedAddressLine1);
130	        String normalizedAddress;
131	        if (structuredAddress) {
132	            normalizedAddress = normalizedAddressLine2.isEmpty()
133	                ? normalizedAddressLine1
134	                : normalizedAddressLine1 + " " + normalizedAddressLine2;
135	        } else {
136	            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
137	        }
138	        List<String> missingFields = new ArrayList<>();
139	        if (isBlank(ownerFieldsDto.getFirstName())) {
140	            missingFields.add("firstName");
141	        }
142	        if (isBlank(ownerFieldsDto.getLastName())) {
143	            missingFields.add("lastName");
144	        }
145	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
146	        if (isBlank(normalizedAddress)) {
147	            missingFields.add("address");
148	        }
149	        if (isBlank(ownerFieldsDto.getCity())) {
150	            missingFields.add("city");
151	        }
152	        if (isBlank(ownerFieldsDto.getTelephone())) {
153	            missingFields.add("telephone");
154	        }
155	        if (!missingFields.isEmpty()) {
156	            throw new InvalidOwnerFieldsException(missingFields);
157	        }
158	        // A supplied registration date may not lie in the future: reject with 400 when the caller
159	        // provides a date later than the server's current date. Checked against the raw supplied value
160	        // (before any business-day adjustment) so a future date is never silently accepted.
161	        if (ownerFieldsDto.getRegistrationDate() != null
162	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
163	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
164	        }
165	        // Determine the effective registration date up front so every downstream use (the daily
166	        // create-limit, the stored value and anything derived from it such as the membership number's
167	        // year segment) works from the same business-day-adjusted date. The effective date is the
168	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
169	        // forward to the following Monday.
170	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
171	            ? ownerFieldsDto.getRegistrationDate()
172	            : LocalDate.now();
173	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
174	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
175	        // already carry this adjusted business day's registration date, no further owners may be
176	        // created for that day.
177	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
178	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
179	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
180	        }
181	        // Flag a bulk signup once more than 80 owners have already been created for this
182	        // business day, sharing the same daily accumulation path as the create-limit rule above.
183	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
184	        // Reject the request when the owner's city is already full: a city that already holds the
185	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
186	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
187	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
188	        }
189	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
190	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
191	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
192	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
193	        // Normalize the telephone into E.164 form; a number that cannot form a valid
194	        // E.164 value is rejected with a 400.
195	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
196	        // Email is optional; when present it must be a syntactically valid address and is
197	        // stored lower-cased. An invalid address is rejected with a 400.
198	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
199	        // Derive the household id up front. It is a deterministic function of the normalized last name
200	        // and the postcode, so owners sharing a last name and postcode independently derive the same
201	        // value and are the same household. It is always computed (never null), regardless of whether
202	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
203	        // duplicate block below.
204	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
205	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
206	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
207	        // All duplicate detection is consolidated into a single derived identity key:
208	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
209	        // part of the key, two members of the same household (same householdId) with different
210	        // telephones have different keys and are both allowed; only an exact whole-key match is a
211	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
212	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
213	        boolean identityInUse = this.clinicService.findAllOwners().stream()
214	            .anyMatch(existing -> identityKey.equals(
215	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
216	        if (identityInUse) {
217	            throw new DuplicateOwnerIdentityException(identityKey);
218	        }
219	        // Because the household is keyed on (last name, postcode), any existing owner carrying this
220	        // computed household id is already a member of this household. A second such owner is rejected
221	        // as a household duplicate (409) unless the caller declares 'sharesHousehold', which bypasses
222	        // the block and admits the owner as a declared household member.
223	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
224	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
225	        if (householdMemberExists && !sharesHousehold) {
226	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), normalizedAddress);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
229	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
230	        // Store the composed, normalized address plus the normalized structured lines. The structured
231	        // lines are only retained when the owner was supplied in the structured form; a flat-address
232	        // owner keeps them null.
233	        owner.setAddress(normalizedAddress);
234	        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
235	        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
236	            ? normalizedAddressLine2 : null);
237	        owner.setTelephone(normalizedTelephone);
238	        owner.setEmail(normalizedEmail);
239	        owner.setHouseholdId(householdId);
240	        // Record how many existing owners (before this create) share this owner's first and last
241	        // name, compared case-insensitively. Computed against the current owners so the new owner
242	        // itself is never counted.
243	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
244	        // Record the size of this owner's household (owners sharing the same householdId) after this
245	        // create: the existing members already stamped with the shared identifier plus this new
246	        // owner. An owner not admitted into any household is a household of one.
247	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
248	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
249	        owner.setBulkSignupWarning(bulkSignupWarning);
250	        // Store the business-day-adjusted effective registration date computed above. This defaults
251	        // to the server's current date when none was supplied and rolls any weekend date forward to
252	        // the following Monday, so everything derived from it (e.g. the membership number's year
253	        // segment) uses the adjusted date.
254	        owner.setRegistrationDate(effectiveRegistrationDate);
255	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
256	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
257	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
258	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
259	        // Compute the base code, then de-duplicate it: if the computed value collides with an
260	        // existing owner's customerCode, append '-<n>' using the smallest n of 2 or more that
261	        // yields a value no existing owner already carries.
262	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
263	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName())));
264	        // Soft-match detection: an owner that cleared the hard-duplicate checks above may still
265	        // resemble an existing owner when it shares that owner's last name and postcode but carries a
266	        // different telephone. A declared household member ('sharesHousehold') is never a suspected
267	        // duplicate, so it is exempt; any other owner reaching here shares no household with an
268	        // existing owner (a household match without 'sharesHousehold' was already rejected above).
269	        // Flag a matched owner as a possible duplicate, recording its id; otherwise the flag is false
270	        // with no matched id.
271	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
272	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
273	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
274	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
275	        this.clinicService.saveOwner(owner);
276	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
277	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
278	        // customer code, the effective registration date, the numeric membership level and the
279	        // assigned membership number.
280	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
281	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
282	            ownerDto.getMembershipNumber());
283	        headers.setLocation(UriComponentsBuilder.newInstance()
284	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
285	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
286	    }
