382	    private static boolean isBlank(String value) {
383	        return value == null || value.trim().isEmpty();
384	    }
385	
386	    /**
387	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
388	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
389	     * compared case-insensitively with collapsed whitespace.
390	     */
391	    private static String collapse(String value) {
392	        if (value == null) {
393	            return "";
394	        }
395	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
396	    }
397	
398	    /**
399	     * Common street-type abbreviations expanded during address normalization.
400	     */
401	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
402	        "ST", "STREET",
403	        "RD", "ROAD",
404	        "AVE", "AVENUE");
405	
406	    /**
407	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
408	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
409	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
410	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
411	     * address maps to itself.
412	     */
413	    private static String normalizeAddress(String value) {
414	        if (value == null) {
415	            return "";
416	        }
417	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
418	        if (collapsed.isEmpty()) {
419	            return "";
420	        }
421	        String[] tokens = collapsed.split(" ");
422	        StringBuilder sb = new StringBuilder(collapsed.length());
423	        for (int i = 0; i < tokens.length; i++) {
424	            if (i > 0) {
425	                sb.append(' ');
426	            }
427	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
428	        }
429	        return sb.toString();
430	    }
431	
432	    /**
433	     * Derive the stable household identifier shared by owners with the same normalized last name
434	     * and postcode. It is a deterministic function of those two values, so every member of a
435	     * household independently derives the same identifier: the first 12 upper-case hex characters
436	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
437	     * an empty segment.
438	     */
439	    private static String householdId(String normalizedLastName, String postcode) {
440	        try {
441	            byte[] digest = MessageDigest.getInstance("SHA-256")
442	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
443	                    .getBytes(StandardCharsets.UTF_8));
444	            StringBuilder sb = new StringBuilder(digest.length * 2);
445	            for (byte b : digest) {
446	                sb.append(String.format("%02x", b));
447	            }
448	            return sb.substring(0, 12).toUpperCase();
449	        }
450	        catch (NoSuchAlgorithmException e) {
451	            throw new IllegalStateException("SHA-256 not available", e);
452	        }
453	    }
454	
455	    /**
456	     * Derive the identity key into which all duplicate detection is consolidated:
457	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
458	     * household id contributes an empty segment. Two owners are duplicates only when their whole
459	     * identity keys are equal.
460	     */
461	    private static String identityKey(String telephone, String email, String householdId) {
462	        return (telephone == null ? "" : telephone)
463	            + "|" + (email == null ? "" : email)
464	            + "|" + (householdId == null ? "" : householdId);
465	    }
466	
467	    /**
468	     * Count the existing owners that share the given first and last name, compared
469	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
470	     * namesakes that already existed at creation time (the new owner itself is not included).
471	     */
472	    private int countNamesakes(String firstName, String lastName) {
473	        return (int) this.clinicService.findAllOwners().stream()
474	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
475	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
476	                && existing.getLastName().equalsIgnoreCase(lastName))
477	            .count();
478	    }
479	
480	    /**
481	     * Count the existing owners that already belong to the given household (i.e. carry the same
482	     * non-null householdId). Called after any existing members have been backfilled with the shared
483	     * identifier but before the new owner is saved, so the returned value reflects the members that
484	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
485	     * new owner is not part of any household ({@code householdId} is null).
486	     */
487	    private int countHouseholdMembers(String householdId) {
488	        if (householdId == null) {
489	            return 0;
490	        }
491	        return (int) this.clinicService.findAllOwners().stream()
492	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
493	            .count();
494	    }
495	
496	    /**
497	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
498	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
499	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
500	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
501	     * including when the new owner has no last name or postcode, since a shared postcode is required
502	     * to match.
503	     */
504	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
505	        if (isBlank(lastName) || isBlank(postcode)) {
506	            return null;
507	        }
508	        return this.clinicService.findAllOwners().stream()
509	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
510	            .filter(existing -> postcode.equals(existing.getPostcode()))
511	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
512	            .min(java.util.Comparator.comparing(Owner::getId))
513	            .orElse(null);
514	    }
515	
516	    /**
517	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
518	     * request to create another owner in it is rejected as a conflict.
519	     */
520	    private static final int MAX_OWNERS_PER_CITY = 50;
521	
522	    /**
523	     * Count the existing owners registered in the given city, compared case-insensitively (as in
524	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
525	     * reflects the owners that already existed at creation time.
526	     */
527	    private int countOwnersInCity(String city) {
528	        return (int) this.clinicService.findAllOwners().stream()
529	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
530	            .count();
531	    }
532	
533	    /**
534	     * The maximum number of owners that may be created on a single day. Once this many owners
535	     * already carry a given day's registration date, a request to create another owner that day is
536	     * rejected with a 429.
537	     */
538	    private static final int MAX_OWNERS_PER_DAY = 100;
539	
540	    /**
541	     * The number of owners that may be created on a single day before the bulk-signup warning is
542	     * flagged. Once more than this many owners already carry a given day's registration date, a
543	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
544	     */
545	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
546	
547	    /**
548	     * Count the existing owners whose registration date is the given day. Called before the new
549	     * owner is saved, so the returned value reflects the owners that already existed at creation
550	     * time.
551	     */
552	    private int countOwnersRegisteredOn(LocalDate date) {
553	        return (int) this.clinicService.findAllOwners().stream()
554	            .filter(existing -> date.equals(existing.getRegistrationDate()))
555	            .count();
556	    }
557	
558	    /**
559	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
560	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
561	     * supplied or defaulted) always falls on a business day.
562	     */
563	    private static LocalDate toBusinessDay(LocalDate date) {
564	        return switch (date.getDayOfWeek()) {
565	            case SATURDAY -> date.plusDays(2);
566	            case SUNDAY -> date.plusDays(1);
567	            default -> date;
568	        };
569	    }
570	
571	    /**
572	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
573	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
574	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
575	     */
576	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
577	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
578	    }
579	
580	    /**
581	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
582	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
583	     * {@code n} of 2 or more that produces a value no existing owner already carries.
584	     */
585	    private String deduplicateCustomerCode(String base) {
586	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
587	            .map(Owner::getCustomerCode)
588	            .filter(java.util.Objects::nonNull)
589	            .collect(java.util.stream.Collectors.toSet());
590	        if (!inUse.contains(base)) {
591	            return base;
592	        }
593	        int n = 2;
594	        while (inUse.contains(base + "-" + n)) {
595	            n++;
596	        }
597	        return base + "-" + n;
598	    }
599	
600	    /**
601	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
602	     */
603	    private static String hash8(String input) {
604	        try {
605	            byte[] digest = MessageDigest.getInstance("SHA-256")
606	                .digest(input.getBytes(StandardCharsets.UTF_8));
607	            StringBuilder sb = new StringBuilder(digest.length * 2);
608	            for (byte b : digest) {
609	                sb.append(String.format("%02x", b));
610	            }
611	            return sb.substring(0, 8).toUpperCase();
612	        }
613	        catch (NoSuchAlgorithmException e) {
614	            throw new IllegalStateException("SHA-256 not available", e);
615	        }
616	    }
617	
618	    /**
619	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
620	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
621	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
622	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
623	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
624	     * always agree.
625	     */
626	    private static String deriveRegion(String postcode, String city) {
627	        if (postcode != null && postcode.matches("\\d{4}")) {
628	            int value = Integer.parseInt(postcode);
629	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
630	                int[] range = entry.getValue();
631	                if (value >= range[0] && value <= range[1]) {
632	                    return entry.getKey();
633	                }
634	            }
635	        }
636	        if (city == null) {
637	            return "UNKNOWN";
638	        }
639	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
640	    }
641	
642	    /**
643	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
644	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
645	     * and accepts any 4-digit postcode.
646	     */
647	    private static final Map<String, String> CITY_REGION = Map.of(
648	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
649	
650	    /**
651	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
652	     * Each entry is a two-element {@code {low, high}} array.
653	     */
654	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
655	        "NSW", new int[] {2000, 2099},
656	        "VIC", new int[] {3000, 3099},
657	        "QLD", new int[] {4000, 4099});
658	
659	    /**
660	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
661	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
662	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
663	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
664	     * 4-digit postcode. A malformed or out-of-range postcode throws an
665	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
666	     */
667	    private static void validatePostcode(String city, String postcode) {
668	        if (postcode == null || postcode.isEmpty()) {
669	            return;
670	        }
671	        if (!postcode.matches("\\d{4}")) {
672	            throw new InvalidOwnerFieldsException(List.of("postcode"));
673	        }
674	        String region = city == null ? null : CITY_REGION.get(city);
675	        if (region == null) {
676	            return;
677	        }
678	        int[] range = REGION_POSTCODES.get(region);
679	        int value = Integer.parseInt(postcode);
680	        if (value < range[0] || value > range[1]) {
681	            throw new InvalidOwnerFieldsException(List.of("postcode"));
682	        }
683	    }
684	
685	    /**
686	     * Required national-number length for each E.164 country calling code we validate: a
687	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
688	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
689	     */
690	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
691	        "1", 10,
692	        "61", 9);
693	
694	    /**
695	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
696	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
697	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
698	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
699	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
700	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
701	     * rejected with a 400.
702	     */
703	    private static String toE164(String raw) {
704	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
705	        boolean hasCountryCode = cleaned.startsWith("+");
706	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
707	        if (!digits.matches("\\d+")) {
708	            throw new InvalidOwnerFieldsException(List.of("telephone"));
709	        }
710	        if (!hasCountryCode) {
711	            if (digits.startsWith("0")) {
712	                digits = digits.substring(1);
713	            }
714	            digits = "61" + digits;
715	        }
716	        if (digits.length() < 8 || digits.length() > 15) {
717	            throw new InvalidOwnerFieldsException(List.of("telephone"));
718	        }
719	        // For a recognised country code, the national number (the digits after the code) must be
720	        // exactly the expected length for that country. Match the longest known code so a shorter
721	        // code that is a prefix of another cannot mask it.
722	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
723	            if (digits.length() <= codeLength) {
724	                continue;
725	            }
726	            String countryCode = digits.substring(0, codeLength);
727	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
728	            if (requiredNationalLength != null) {
729	                if (digits.length() - codeLength != requiredNationalLength) {
730	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
731	                }
732	                break;
733	            }
734	        }
735	        return "+" + digits;
736	    }
737	
738	    /**
739	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
740	     * and a domain with at least one dot-separated label, none of which contain whitespace or
741	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
742	     */
743	    private static final Pattern EMAIL_PATTERN =
744	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
745	
746	    /**
747	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
748	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
749	     */
750	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
751	        "mailinator.com", "tempmail.com", "guerrillamail.com");
752	
753	    /**
754	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
755	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
756	     * domain is not on the disposable-domain blocklist, otherwise an
757	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
758	     * address is returned lower-cased.
759	     */
760	    private static String normalizeEmail(String email) {
761	        if (email == null || email.isEmpty()) {
762	            return null;
763	        }
764	        String trimmed = email.trim();
765	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
766	            throw new InvalidOwnerFieldsException(List.of("email"));
767	        }
768	        String normalized = trimmed.toLowerCase();
769	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
770	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
771	            throw new InvalidOwnerFieldsException(List.of("email"));
772	        }
773	        return normalized;
774	    }
775	}
